class Contador {
  int valor;
  static int criados = 0;
  Contador(int valor) {
    this.valor = valor;
    criados++;
  }
  Contador() {
    this(5);
    valor += 2;
  }
  public static void main(String[] args) {
    Contador c1 = new Contador();
    Contador c2 = new Contador(c1.valor);
    c1.valor += criados;
    System.out.println(c1.valor + " " + c2.valor + " " + criados);
  }
}

abstract class Pessoa {
  String nome;
  Pessoa(String nome) {
    this.nome = nome;
  }
  abstract String descricao();
}
class Professor extends Pessoa {
  Professor(String nome) {
  }
  String descricao() {
    return "Professor: " + nome;
  }
}
public class Teste {
  public static void main(String[] args) {
    Professor p = new Professor("Ana");
    System.out.println(p.descricao());
  }
}

abstract class Forma {
  abstract double calcularArea();
}
class Retangulo extends Forma {
  double largura = 4, altura = 5;
  double calcularArea() {
    return largura * altura;
  }
}
class Triangulo extends Forma {
  double base = 6, altura = 3;
  double calcularArea() {
    return (base * altura) / 2;
  }
}
public class Teste {
  public static void main(String[] args) {
    Forma[] formas = { new Retangulo(), new Triangulo() };
    double soma = 0;
    for (Forma f : formas) {
      soma += f.calcularArea();
    }
    System.out.println(soma);
  }
}

